// ==================== Turnover Day booking block (cross-module, see header note) ====================

Given('a ranch exists with a configured Turnover Day', async function (this: ScenarioContext) {
  // Ranch Configuration precondition — Turnover Day is set via Initial Settings (FR-RANCH-001),
  // consumed here by FR-RANCH-002's booking-block rule.
  expect(this.testData.RanchName).toBeTruthy();
});

When('a booking-capable user attempts to create a booking on the ranch\'s Turnover Day', async function (this: ScenarioContext) {
  await this.page.getByRole('button', { name: 'New Booking' }).click();
  const row = this.testData as Record<string, string>;
  await this.page.getByLabel(/Ranch/i).first().click();
  await this.page.getByRole('option', { name: row.RanchName }).click();
  await this.page.getByLabel(/Check-?in/i).first().fill(row.CheckInDate);
  await this.page.getByRole('button', { name: /submit|create booking/i }).click();
});

When('a booking-capable user creates a booking on a date that is not the Turnover Day', async function (this: ScenarioContext) {
  const row = this.testData as Record<string, string>;
  await this.page.getByRole('button', { name: 'New Booking' }).click();
  await this.page.getByLabel(/Ranch/i).first().click();
  await this.page.getByRole('option', { name: row.RanchName }).click();
  await this.page.getByLabel(/Check-?in/i).first().fill(row.CheckInDate);
  await this.page.getByRole('button', { name: /submit|create booking/i }).click();
});

Then('booking creation should be blocked with an appropriate error message', async function (this: ScenarioContext) {
  await expect(this.page.getByText(/turnover day|not available|blocked/i)).toBeVisible();
});

Then('the booking should be created successfully without a Turnover Day block', async function (this: ScenarioContext) {
  await expect(this.page.getByText(/turnover day|not available|blocked/i)).toHaveCount(0);
});

